INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 29, 'theory', 'Quiz: the optimizer');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 29, 0, 'What is the optimizer''s choice of plan based on?', '["The order of words in the query", "A random pick among the possible plans", "A cost estimate that relies on statistics and the estimated number of rows", "The size of the log file"]', 2, 'The optimizer considers physical plans and picks the cheapest by its own estimate; an error in the row estimate leads to a bad plan.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 29, 1, 'Why is the estimate for several conditions often inaccurate?', '["The optimizer cannot count", "The fractions of the conditions are multiplied under the independence assumption, and related columns (city and postal code) violate it", "The conditions always hold at the same time", "The database stores only one condition"]', 1, 'The cure is extended statistics on related columns and refreshing the statistics with the ANALYZE command.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 29, 2, 'When are nested loops better than a hash join?', '["When the outer table is small and the inner one has a suitable index", "When both tables are huge and have no indexes", "When the join condition is an inequality and there is plenty of memory", "Never"]', 0, 'Hash and merge are better for large sets and equality; for inequalities only nested loops fit.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 29, 3, 'What should you look for first in the output of EXPLAIN ANALYZE?', '["Only the total query time", "The color of the nodes", "The number of spaces", "An estimate that differs from the actual value by an order of magnitude, a scan of a large table instead of a lookup, and the most expensive node"]', 3, 'You start from the most expensive node and go deeper, comparing the expected number of rows with the real one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 29, 4, 'Why can a prepared query suddenly become slow for certain parameter values?', '["The client ran out of memory", "The log overflowed", "A plan that is optimal for a frequent value is bad for a rare one: the generic plan does not account for data skew", "The indexes were deleted"]', 2, 'The fixes: custom plans, separate queries for edge cases, and tuning the plan mode.');
